=== 5.58.13
{
  "verse_id": "5.58.13",
  "sarga": 58,
  "verse": "13",
  "ambiguous_marker": false,
  "sanskrit_iast": "putreti madhurāṃ vāṇīṃ manaḥ prahlādayann iva । pitṛvyaṃ cāpi māṃ viddhi sakhāyaṃ mātariśvanaḥ ॥13॥",
  "leonov_ru": "«Сын [мой]», - сладостной речью, словно освежающей душу, «Знай, что я брат твоего отца, друг (бога ветра) Матаришвана.",
  "commentary": {
    "bhusana": "पितृव्यं चापि मां विद्धि सखायं मातरिश्वनः ।\n\nमैनाकमिति विख्यातं निवसन्तं महोदधौ\nपितृव्यं चेति । पितृव्यत्वे हेतुमाह सखायमिति । पितृसखत्वात् पितृव्यत्वव्यपदेश इत्यर्थः",
    "siromani": "पितृव्यं चेति । पितृव्यत्वे हेतुमाह-- सखायमिति । पितृसखत्वात् पितृव्यत्वव्यपदेश इत्यर्थः"
  },
  "pratika_check": {
    "bhusana": {
      "pratika_iast": "pitrvyan capi nan viddhi",
      "matches_verse": true
    },
    "siromani": {
      "pratika_iast": "pitrvyan ceti",
      "matches_verse": true
    }
  }
}
=== 5.58.16
{
  "verse_id": "5.58.16",
  "sarga": 58,
  "verse": "16",
  "ambiguous_marker": false,
  "sanskrit_iast": "vajreṇa bhagavān pakṣau cicchedaiṣāṃ sahasraśaḥ । ahaṃ tu mokṣitas tasmāt tava pitrā mahātmanā ॥16॥",
  "leonov_ru": "Ваджрой владыка отрубил оба крыла у тысяч гор. Я же от этого был спасен твоим великим духом отцом.",
  "commentary": {
    "siromani": "अहमिति । तदा तस्मिन् समये तव पित्रा अहं वरुणालये प्रक्षिप्तः अत एव तस्मात्पक्षछेदात् मोचितः"
  },
  "pratika_check": {
    "siromani": {
      "pratika_iast": "ahaniti",
      "matches_verse": true
    }
  }
}
=== 5.58.17
{
  "verse_id": "5.58.17",
  "sarga": 58,
  "verse": "17",
  "ambiguous_marker": false,
  "sanskrit_iast": "mārutena tadā vatsa prakṣipto vāruṇālaye । rāghavasya mayā sāhye vartitavyam ariṃdama ॥17॥",
  "leonov_ru": "Марута бросил меня, сын мой, в обитель Варуны (океан). Должен я помочь Рагхаве, губитель врагов.",
  "commentary": {
    "bhusana": "रामस्य च मया साह्ये वर्तितव्यमरिन्दम ।\n\nरामो धर्मभृतां श्रेष्ठो महेन्द्रसमविक्रमः\nसाह्ये साहाय्ये । साहाय्यकरणे हेतुमाह रामो धर्मभृतां श्रेष्ठ इति",
    "siromani": "राघवस्येति । धर्मभृतां श्रेष्ठः यो रामः तस्य राघवस्य साह्ये साहाय्ये मया वर्तितव्यम्"
  },
  "pratika_check": {
    "bhusana": {
      "pratika_iast": "ranasya ca naya sahye",
      "matches_verse": true
    },
    "siromani": {
      "pratika_iast": "raghavasyeti",
      "matches_verse": true
    }
  }
}

=== 5.58.27
{
  "verse_id": "5.58.27",
  "sarga": 58,
  "verse": "27",
  "ambiguous_marker": false,
  "sanskrit_iast": "kartum arhasi rāmasya sāhayyaṃ viṣaye satī । atha vā maithilīṃ dṛṣṭvā rāmaṃ cākliṣṭakāriṇam ॥27॥",
  "leonov_ru": "Ты, пребывающая в [его] земле, должна помочь Раме. Или же, повидав [сначала] Майтхили и Раму, неутомимого в деяниях,",
  "commentary": {
    "tilaka": "विषये सति तदीयदेशे सति विद्यमाने । मैथिलीदर्शननिवेदनार्थं रामं च दृष्ट्वा ।। 5.58.27,28 ।।\n\nनातिवर्तेत नातिक्रमेत । मां प्राप्तः । मदाहारतां प्राप्तो न गच्छेदित्यर्थः",
    "siromani": "कर्तुमिति । विषये रामदेशे सति हे विद्यमाने साहाय्यं कर्तुमर्हसि । अर्धं पृथक् । ननु रामादहं न बिभेमीति त्वां भक्षयिष्याम्येवेत्यत आह अथवेति । प्रतिशृणोमि प्रतिज्ञां करोमि । अर्धद्वयमेकान्वयि"
  },
  "pratika_check": {
    "tilaka": {
      "pratika_iast": "visaye sati tadiyadese sati",
      "matches_verse": true
    },
    "siromani": {
      "pratika_iast": "kartuniti",
      "matches_verse": true
    }
  }
}
=== 5.58.29
{
  "verse_id": "5.58.29",
  "sarga": 58,
  "verse": "29",
  "ambiguous_marker": false,
  "sanskrit_iast": "abravīn nātivarteta kaś cid eṣa varo mama । evam uktaḥ surasayā daśayojanam āyataḥ ॥29॥",
  "leonov_ru": "Сказала: «Никто меня не избегнет, таков мой дар». Я, когда Сураса мне так сказала, был высотой в десять йоджан.",
  "commentary": {
    "bhusana": "एवमुक्तः सुरसया दशयोजनमायतः ।\n\nततो ऽर्धगुणविस्तारो बभूवाहं क्षणेन तु ।\n\nमत्प्रमाणानुरूपं च व्यादितं तु मुखं तया\nएवमुक्त इति । तत इति । अर्धगुणविस्तारः अत्रार्धशब्दः एकदेशवाची । किंचिदधिकविस्तारो ऽभवमित्यर्थः । एवमेवार्थः, प्रथमसर्गोक्तशतयोजनविस्तारस्तु विरुद्धः । तद्ग्रन्थः कल्पितश्चेत्युक्तम् । मत्प्रमाणेति । व्यादितं व्यात्तम्",
    "siromani": "एवमिति । दशयोजनमायतः स्वाभाविकदशयोजनविस्तृतो ऽहं यस्मिन् काले सुरसया एवमुक्तस्तस्मिन् काले अर्धगुणविस्तारः पञ्चयोजनविस्तृतो बभूव । तया सुरसया तु क्षणेनैव मत्प्रमाणाधिकं मत्प्रमाणादधिकं मुखं व्यादितं तदास्यं व्यादितं दृष्ट्वा अहं ह्रस्वं सूक्ष्मरूपमकरवम् ।। 5.58.29,30 ।।\n\nतस्मिन्निति । अङ्गुष्ठसंमितः यो ऽहं बभूव सः तद्वक्रमभिपत्य प्रविश्य क्षणान्निर्गतो ऽस्मि । अर्धद्वयमेकान्वयि"
  },
  "pratika_check": {
    "bhusana": {
      "pratika_iast": "evanuktah surasaya dasayojananayatah",
      "matches_verse": true
    },
    "siromani": {
      "pratika_iast": "evaniti",
      "matches_verse": true
    }
  }
}
=== 5.58.30
{
  "verse_id": "5.58.30",
  "sarga": 58,
  "verse": "30",
  "ambiguous_marker": false,
  "sanskrit_iast": "tato 'rdhaguṇavistāro babhūvāhaṃ kṣaṇena tu । matpramāṇādhikaṃ caiva vyāditaṃ tu mukhaṃ tayā ॥30॥",
  "leonov_ru": "Затем в единый миг стал я в половину этого роста больше [15 йоджан]. Она же раскрыла пасть еще шире моего размера.",
  "commentary": {
    "bhusana": "तद्दृष्ट्वा व्यादितं चास्यं ह्रस्वं ह्यकरवं वपुः ।\n\nतस्मिन् मुहूर्ते च पुनर्बभूवाङ्गुष्ठमात्रकः"
  },
  "pratika_check": {
    "bhusana": {
      "pratika_iast": "taddrstva vyaditan casyan hrasvan",
      "matches_verse": true
    }
  }
}
=== 5.58.36
{
  "verse_id": "5.58.36",
  "sarga": 58,
  "verse": "36",
  "ambiguous_marker": false,
  "sanskrit_iast": "so 'haṃ vigatavegas tu diśo daśa vilokayan । na kiṃ cit tatra paśyāmi yena me vihatā gatiḥ ॥36॥",
  "leonov_ru": "Утратив скорость, я оглядел десять сторон света, Но не увидел ничего, что бы преградило мой путь.",
  "commentary": {
    "tilaka": "अर्धगुणविस्तारो ऽर्धस्य दशयोजनार्धस्य पञ्चयोजनस्य गुण आवृत्तिस्तद्विस्तारः । दशयोजनविस्तार इति यावत् । पूर्वं दशयोजनविस्तारोक्त्या ऽ ऽनुगुण्येनैवं व्याख्यातम्",
    "bhusana": "ततो मे बुद्धिरुत्पन्ना किं नाम गगने मम ।\n\nईदृशो विघ्न उत्पन्नो रूपं यत्र न दृश्यते",
    "siromani": "स इति । येन मे गतिर्विहता तत् किंचिन्न पश्यामि"
  },
  "pratika_check": {
    "tilaka": {
      "pratika_iast": "ardhagunavistaro rdhasya dasayojanardhasya pancayojanasya",
      "matches_verse": true
    },
    "bhusana": {
      "pratika_iast": "tato ne buddhirutpanna kin",
      "matches_verse": true
    },
    "siromani": {
      "pratika_iast": "sa",
      "matches_verse": false,
      "content_containment": 0.188,
      "content_anchor": true
    }
  }
}

=== 5.58.44
{
  "verse_id": "5.58.44",
  "sarga": 58,
  "verse": "44",
  "ambiguous_marker": false,
  "sanskrit_iast": "sā visṛṣṭabhujā bhīmā papāta lavaṇāmbhasi । mayā parvatasaṃkāśā nikṛttahṛdayā satī ॥44॥",
  "leonov_ru": "Она, раскинув руки, ужасная, упала в соленые воды, Подобная горе, будучи лишена мной сердца.",
  "commentary": {
    "tilaka": "विसुष्टभुजा विप्रकीर्णभुजा",
    "siromani": "सेति । मया ऽतिकृत्तहृदया ताडितान्तरा अत एव विमृष्टौ विकीर्णौ भुजौ यस्याः सा असती लवणाम्भसि निपपात"
  },
  "pratika_check": {
    "tilaka": {
      "pratika_iast": "visustabhuja viprakirnabhuja",
      "matches_verse": false,
      "content_containment": 0.0
    },
    "siromani": {
      "pratika_iast": "seti",
      "matches_verse": false,
      "content_containment": 0.333,
      "content_anchor": true
    }
  }
}
=== 5.58.48
{
  "verse_id": "5.58.48",
  "sarga": 58,
  "verse": "48",
  "ambiguous_marker": false,
  "sanskrit_iast": "praviṣṭo 'ham avijñāto rakṣobhir bhīmavikramaiḥ । tatrāhaṃ praviśataś cāpi kalpāntaghanasaprabhā ॥48॥",
  "leonov_ru": "Вошел я, не замеченный стражами, наделенными грозной мощью. Когда я вошел туда, подобная туче конца времен,",
  "commentary": {
    "bhusana": "प्रदोषकाले प्रविशं भीतया ऽहं तयोदितः ।\n\nअहं लङ्कापुरी वीर निर्जिता विक्रमेण ते\nतत्र प्रविशतश्चापि कल्पान्तघनसन्निभा ।\n\nअट्टहासं विमुञ्चन्ती नारी काप्युत्थिता पुरः",
    "siromani": "तत्रेति । तत्र लङ्कायां प्रविशतो मम पुरः अग्रे कल्पान्तघनसंनिभा एका नारी उत्थिता"
  },
  "pratika_check": {
    "bhusana": {
      "pratika_iast": "pradosakale pravisan bhitaya han",
      "matches_verse": true
    },
    "siromani": {
      "pratika_iast": "tatreti",
      "matches_verse": true
    }
  }
}
=== 5.58.49
{
  "verse_id": "5.58.49",
  "sarga": 58,
  "verse": "49",
  "ambiguous_marker": false,
  "sanskrit_iast": "aṭṭahāsam vimuñcantī nārī kāpyutthitā puraḥ । jighāṃsantīm tatas tām tu jvaladagniśiroruhām ॥49॥",
  "leonov_ru": "Издавая громкий смех, предстала передо мной некая женщина. Тогда ее, желающую [меня] убить, у которой волосы на голове пылали огнем,",
  "commentary": {
    "bhusana": "जिघांसन्तीं ततस्तां तु ज्वलदग्निशिरोरुहाम् ।\n\nसव्यमुष्टिप्रहारेण पराजित्य सुभैरवाम्",
    "siromani": "जिघां सन्तीमिति । जिघांसन्तीं तां सव्यमुष्टिप्रहारेण पराजित्य तया उदितः कथितवृत्तान्तो ऽहं प्रविशं प्राविशम् । सार्धश्लोक एकान्वयी ।। 5.58.49,50 ।।\n\nतद्वचनाकारमाह अहमिति । यस्मात् ते त्वया अहं निर्जिता तस्मात् सर्वरक्षांसि त्वं विजेता ऽसि"
  },
  "pratika_check": {
    "bhusana": {
      "pratika_iast": "jighansantin tatastan tu jvaladagnisiroruhan",
      "matches_verse": true
    },
    "siromani": {
      "pratika_iast": "jighan santiniti",
      "matches_verse": true
    }
  }
}
=== 5.58.50
{
  "verse_id": "5.58.50",
  "sarga": 58,
  "verse": "50",
  "ambiguous_marker": false,
  "sanskrit_iast": "savyamuṣṭiprahāreṇa parājitya subhairavām । pradoṣakāle praviśam bhītayāham tayoditaḥ ॥50॥",
  "leonov_ru": "Я ударом левого кулака поразил, ужасную. В вечерних сумерках вошел я [в Ланку], и она [та женщина], испуганная, мне сказала:",
  "commentary": {
    "tilaka": "सुभैरवामतिशयेन भयङ्कररूपाम् । प्रविशं प्राविशम् ।। 5.58.50,51 ।।\n\nसर्वरात्रं सर्वां रात्रीम् । अल्पशेषाय रात्रावशोकवनिकायां दर्शनादेवमुक्तिः"
  },
  "pratika_check": {
    "tilaka": {
      "pratika_iast": "subhairavanatisayena bhayankararupan",
      "matches_verse": true
    }
  }
}
=== 5.58.51
{
  "verse_id": "5.58.51",
  "sarga": 58,
  "verse": "51",
  "ambiguous_marker": false,
  "sanskrit_iast": "aham laṅkāpurī vīra nirjitā vikrameṇa te । yasmāt tasmād vijetāsi sarvarakṣāṃsyaśeṣataḥ ॥51॥",
  "leonov_ru": "«О герой! Раз я, город Ланка, побеждена твоей мощью, То победишь ты и всех ракшасов без исключения».",
  "commentary": {
    "bhusana": "यस्मात्तस्माद्विजेतासि सर्व रक्षांस्यशेषतः"
  },
  "pratika_check": {
    "bhusana": {
      "pratika_iast": "yasnattasnadvijetasi sarva raksansyasesatah",
      "matches_verse": true
    }
  }
}

=== 5.58.71
{
  "verse_id": "5.58.71",
  "sarga": 58,
  "verse": "71",
  "ambiguous_marker": false,
  "sanskrit_iast": "rākṣasādhama rāmasya bhāryām amitatejasaḥ । ikṣvākuvaṃśanāthasya snuṣāṃ daśarathasya ca ॥71॥",
  "leonov_ru": "«О низкий ракшас! Жене Рамы, наделенного безмерной мощью, Господина рода Икшваку, невестке Дашаратхи",
  "commentary": {
    "bhusana": "न त्वं रामस्य सदृशो दास्ये ऽप्यस्य न युज्यसे ।\n\nयज्ञीयः सत्यवादी च रणश्लाघी च राघवः\nराक्षसाधम रामस्य भार्यममिततेजसः ।\n\nइक्ष्वाकुकुलनाथस्य स्नुषां दशरथस्य च ।\n\nअवाच्यं वदतो जिह्वा कथं न पतिता तव"
  },
  "pratika_check": {
    "bhusana": {
      "pratika_iast": "na tvan ranasya sadrso",
      "matches_verse": true
    }
  }
}
=== 5.58.72
{
  "verse_id": "5.58.72",
  "sarga": 58,
  "verse": "72",
  "ambiguous_marker": false,
  "sanskrit_iast": "avācyaṃ vadato jihvā kathaṃ na patitā tava । kiṃsvid vīryaṃ tavānārya yo māṃ bhartur asaṃnidhau ॥72॥",
  "leonov_ru": "У тебя, говорящего недолжные речи как язык не отсох (не отвалился)? О неблагородный! Каково было твое мужество, когда ты меня в отсутствие мужа",
  "commentary": {
    "tilaka": "कथंवृत्तः कीदृग्व्यापारः ।। 5.58.4,5 ।।\n\nचिन्तनीयनिश्चयमेवाह-- यश्चेति । रक्षितव्यं रामसंनिधौ गोपनीयम् अवक्तव्यमिति यावत् । अवक्तव्यं च यत्तच्चिन्तयिष्यामः, अतस्तत्पृष्टं सर्वमात्मवान्भवान्व्याकरोतु",
    "bhusana": "किंचिद्वीर्यं तवानार्य यो मां भर्तुरसन्निधौ ।\n\nअपहृत्यागतः पाप तेनादृष्टो महात्मना",
